package net.civeira.phylax.features.document.theme.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.ThemeBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class ThemeBatchController implements ThemeBatchApi {

  /**
   * Theme
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ThemeDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ThemeDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final ThemeEnableController enableController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param name
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response themeApiBatchDelete(final List<String> uids, final String search,
      final Boolean global, final String name, final String tenant, final List<String> tenants) {
    return deleteController.themeApiBatchDelete(uids, search, global, name, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response themeApiBatchDeleteQuery(final String batchId) {
    return deleteController.themeApiBatchDeleteQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param name
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response themeApiBatchDisable(final List<String> uids, final String search,
      final Boolean global, final String name, final String tenant, final List<String> tenants) {
    return disableController.themeApiBatchDisable(uids, search, global, name, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response themeApiBatchDisableQuery(final String batchId) {
    return disableController.themeApiBatchDisableQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param name
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response themeApiBatchEnable(final List<String> uids, final String search,
      final Boolean global, final String name, final String tenant, final List<String> tenants) {
    return enableController.themeApiBatchEnable(uids, search, global, name, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response themeApiBatchEnableQuery(final String batchId) {
    return enableController.themeApiBatchEnableQuery(batchId);
  }
}
